def verify(witness):
    def is_squarefree(k):
        if k < 1:
            return False
        d = 2
        while d * d <= k:
            if k % (d * d) == 0:
                return False
            d += 1
        return True

    r = witness['range']
    lo, hi, lmax = r['n_min'], r['n_max'], witness['l_max']
    if r['parity'] != 'odd':
        raise AssertionError('bad parity')
    if lo % 2 != 1 or lo < 3 or hi < lo or lmax < 0:
        raise AssertionError('bad range')
    for n in range(lo, hi + 1, 2):
        found = False
        for l in range(0, lmax + 1):
            p2 = 2 ** l
            if p2 >= n:
                break
            k = n - p2
            if k >= 1 and is_squarefree(k):
                found = True
                break
        if not found:
            raise AssertionError('no decomposition for n=%d' % n)

WITNESS = {"range": {"n_min": 3, "n_max": 199, "parity": "odd"}, "l_max": 7}
verify(WITNESS)
